mapper.select:
SELECT * FROM ( SELECT T.*, ROWNUM RN FROM ( SELECT D.INVOICEDETAILID, M.INVOICEID, nvl(M.Invoicenumber, ' ') Invoicenumber, NVL(M.SUBMITNUMBER, ' ') SUBMITNUMBER, NVL(D.CHECKSTATUS, ' ') CHECKSTATUS, NVL(D.CHECKRESULT, '未检') CHECKRESULT, NVL(D.MATERIALTYPE, ' ') MATERIALTYPE, NVL(D.DELIVERNUMBER, ' ') DELIVERNUMBER, NVL(D.PO, ' ') PO, NVL(P.Pnid, ' ') PNID, NVL(D.PN, ' ') PN, NVL(D.VENDORCODE, ' ') VENDORCODE, NVL(D.VENDORNAME, ' ') VENDORNAME, NVL(D.TOTALQTY, 0) TOTALQTY, D.TOTALQTY - NVL(D.REMAININGQTY, 0) REMAININGQTY, NVL(D.VENDORLOTNO, ' ') VENDORLOTNO, NVL(P.PARTSPEC, ' ') PARTSPEC, NVL(P.LARGECATEGORY, ' ') LARGECATEGORY, NVL(P.Unitqty, 1) UNITQTY, NVL(p.ESDLEVEL, ' ') ESDLEVEL, NVL(p.MSDLEVEL, ' ') MSDLEVEL, NVL(p.LEADFREE, ' ') LEADFREE, NVL(d.rmapo, ' ') RMAPO, NVL(P.CONTROL_FLAG, 'N') CONTROL_FLAG, NVL(GETMARK(D.PN), ' ') MARK, NVL(V.LAST_NAME, ' ') CAIGOUYUANNAME, 'Y' APPROVED_FLAG,
nvl(d.DATETIME,sysdate) DATETIME, nvl(d.LIMITEDDAY,sysdate) LIMITEDDAY, nvl(d.PACKSTYLE,' ') PACKSTYLE, nvl(d.VENDORWEEKCODE,' ') VENDORWEEKCODE, nvl(d.VENDORSN,'/') VENDORSN, nvl(d.MATERIALSTORAGE,' ') MATERIALSTORAGE, P.UNIT FROM RMM_INVOICE M, RMM_INVOICEDETAIL D, PARTNUMBER P, cux_e2m_po_buyer_v@Jcd_Demo V WHERE 1 = 1 AND M.INVOICEID = D.Invoiceid(+) AND D.PN = P.PN(+) AND D.PO = V.PO_NUMBER(+)
AND M.STATE IN ('OH','DEFAULT') AND D.CHECKSTATUS IN ('OPEN','PRINTING') AND P.CONTROL_FLAG='Y' AND D.Invoicenumber LIKE 'TSIQC%'
AND D.PO = #{poNumber}
AND D.PN = #{partNumber}
AND ( M.INVOICENUMBER LIKE '%' || #{keyword} || '%' OR D.PN LIKE '%' || #{keyword} || '%' OR D.PO LIKE '%' || #{keyword} || '%' OR D.VENDORNAME LIKE '%' || #{keyword} || '%' )
ORDER BY D.POLINENUM ASC ) T WHERE ROWNUM <= #{endRow} ) WHERE RN > #{startRow}

mapper.update:
UPDATE RMM_INVOICEDETAIL
SET CHECKSTATUS = 'CLOSE'
WHERE INVOICEDETAILID = #{id}
